import React from "react";
import { AbsoluteFill, Audio, Img, interpolate, staticFile, useCurrentFrame } from "remotion";
import { AZUL, BACK, BC, BCN, BG, BLUE, CARD, CLARO, Cap, Clock, Col, ESCURO, EDGE, GOLD, GREEN, INOUT, Label, Laptop, Ln, SUB, Tag, Tema, Th, WHITE, cl, k } from "./FormacaoKit";
import { Diploma, Pin, Seal, Shield, Whats } from "./FormacaoIcones";

// TUTORES.ED (cliente hélio silva) — "Formação acelerada". Pedido sem roteiro: só 3 artes de divulgação.
// Motion (pouco material: as artes são prints pequenos). Identidade das artes; voz o locutor.
// v2 (retorno "dinamicidade, inversão de fundo e tirar os espaços na narração"): voz com as pausas encurtadas
// (src/voz-v2-curta.wav; os tempos abaixo continuam na voz original e v() desconta os cortes), fundo alternando
// marinho → azul → claro a cada cena, câmera aproximando e girando em toda cena, batida de câmera nas palavras-chave
// e texto entrando com escala e giro.
// v3 (retorno "remover ensino fundamental, só o médio; focar no final Arquitetando seu futuro"): a frase do supletivo
// foi regravada sem "fundamental" e a frase final "Tutores ponto É Dê. Arquitetando seu futuro." acrescentada
// (tools/monta_voz_v3.py + corte_v3.py em (arquivo do cliente) → src/voz-v3-curta.wav). Os tempos continuam na voz v2
// original; v() leva para a voz nova. Cartão final novo com o slogan em destaque.
// Transições: inundação azul → empurrão p/ esquerda → p/ cima → íris saindo do relógio → p/ direita →
// íris saindo do cadeado "Privada" → p/ baixo → p/ esquerda → p/ cima (cartão do slogan).

export const FO_FPS = 30;
export const FO_DUR = 35;
export const FO_FRAMES = Math.round(FO_DUR * FO_FPS);
const VO = 0.15;
// tempo da voz v2 original → voz v3 montada: até 3,45 s igual; a frase do supletivo foi regravada (âncoras palavra a
// palavra pela transcrição; "fundamental" sumiu); de 11,2 s em diante a voz original anda 1,27 s mais cedo
const NOVA: [number, number][] = [[3.45, 3.45], [3.74, 3.5], [4.5, 4.47], [5.13, 5.01], [6.67, 6.48], [6.91, 6.9], [7.63, 7.46], [8.81, 8.0], [9.24, 8.34], [9.51, 8.5], [9.8, 8.78], [10.14, 9.07], [11.2, 9.93]];
const montada = (s: number) => {
  if (s <= 3.45) return s;
  if (s >= 11.2) return s - 1.27;
  let i = 0;
  while (s > NOVA[i + 1][0]) i++;
  const [a0, b0] = NOVA[i], [a1, b1] = NOVA[i + 1];
  return b0 + ((s - a0) / (a1 - a0)) * (b1 - b0);
};
// pausas cortadas da voz montada, de src/voz-v3-cortes.json
const CORTES: [number, number][] = [[12.59, 12.88], [18.16, 18.59], [22.93, 23.41], [27.64, 28.13], [29.68, 29.99], [31.07, 31.2], [33.29, 34.54]];
const curta = (s: number) => {
  let d = 0;
  for (const [a, b] of CORTES) {
    if (s >= b) d += b - a;
    else if (s > a) d += s - a;
  }
  return s - d;
};
const v = (s: number) => curta(montada(s)) + VO;
// frase final (já em tempo da voz nova, medido pelo volume): "Tutores ponto É Dê" e "Arquitetando seu futuro"
const FIN = { tutores: 29.29 + VO, arq: 31.27 + VO, seu: 31.57 + VO, futuro: 31.77 + VO };

// cortes
const C1 = v(3.5), C2 = v(6.6), C3 = v(9.45), C4 = v(11.25), C5 = v(13.62), C6 = v(19.6), C7 = v(24.45), C8 = v(29.2), C9 = FIN.tutores - 0.1;

type Dir = "left" | "right" | "up" | "down" | "zoom" | "none";
const PUSH = 0.5;
// cena com o próprio fundo: empurrões andam colados (a cena seguinte encosta na anterior, as duas cores aparecem),
// íris abre um círculo a partir de um ponto; câmera aproxima e gira devagar o tempo todo; batida nas palavras-chave
const Scene: React.FC<{ t: number; a: number; b: number; inn: Dir; out: Dir; tema: Tema; dir?: number; hits?: number[]; iris?: [number, number]; children: React.ReactNode }> = ({ t, a, b, inn, out, tema, dir = 1, hits = [], iris, children }) => {
  const pre = inn === "none" ? 0 : PUSH / 2 + 0.2;
  if (t < a - pre || t > b + PUSH / 2 + 0.05) return null;
  const e = interpolate(t, [a - PUSH / 2, a + PUSH / 2], [0, 1], { ...cl, easing: INOUT });
  const o = interpolate(t, [b - PUSH / 2, b + PUSH / 2], [0, 1], { ...cl, easing: INOUT });
  const life = interpolate(t, [a - 0.3, b + 0.3], [0, 1], cl);
  const dx = dir * (-15 + 30 * life);
  let x = 0, y = 0, s = 1.0 + 0.06 * life, blur = 0, op = 1, rot = dir * (-1.6 + 3.2 * life);
  for (const h of hits) if (t >= h) s += 0.05 * (1 - k(t, h, 0.4));
  const vi = Math.sin(Math.PI * e), vo = Math.sin(Math.PI * o);
  if (inn === "left") { x += 1080 * (1 - e); blur += 18 * vi; }
  if (inn === "right") { x -= 1080 * (1 - e); blur += 18 * vi; }
  if (inn === "up") { y += 1920 * (1 - e); blur += 18 * vi; }
  if (inn === "down") { y -= 1920 * (1 - e); blur += 18 * vi; }
  if (inn === "zoom") { s *= 0.8 + 0.2 * k(t, a - 0.3, 0.7); }
  if (out === "left") { x -= 1080 * o; blur += 18 * vo; }
  if (out === "right") { x += 1080 * o; blur += 18 * vo; }
  if (out === "up") { y -= 1920 * o; blur += 18 * vo; }
  if (out === "down") { y += 1920 * o; blur += 18 * vo; }
  if (out === "zoom") { s *= 1 + 2.2 * o * o; op = 1 - o; }
  const r = iris ? interpolate(t, [a - 0.35, a + 0.35], [0, 1], { ...cl, easing: INOUT }) : 1;
  const lx = 540 + Math.sin(t * 0.6 + a) * 260, ly = 900 + Math.cos(t * 0.5 + a) * 380;
  const glow = tema.bg === BLUE ? "rgba(120,180,255,0.35)" : tema.bg === WHITE ? "rgba(47,123,255,0.10)" : "rgba(47,123,255,0.16)";
  return (
    <AbsoluteFill style={{ clipPath: iris && r < 1 ? `circle(${(r * 2300).toFixed(0)}px at ${iris[0]}px ${iris[1]}px)` : undefined }}>
      <AbsoluteFill style={{ transform: `translate(${x.toFixed(1)}px, ${y.toFixed(1)}px)`, opacity: op }}>
        <AbsoluteFill style={{ background: tema.bg }} />
        <AbsoluteFill style={{ background: `radial-gradient(900px 900px at ${lx.toFixed(0)}px ${ly.toFixed(0)}px, ${glow} 0%, rgba(0,0,0,0) 70%)` }} />
        <AbsoluteFill style={{ transform: `translateX(${dx.toFixed(1)}px) scale(${s.toFixed(4)}) rotate(${rot.toFixed(3)}deg)`, filter: blur > 0.3 ? `blur(${blur.toFixed(1)}px)` : undefined }}>
          <Th.Provider value={tema}>{children}</Th.Provider>
        </AbsoluteFill>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ───────── 1 · gancho: a barra de progresso com o capelo é o fio; no fim ela inunda a tela de azul ─────────
const CAPX = (t: number) => 240 + 600 * interpolate(t, [0.2, v(3.0)], [0, 1], { ...cl, easing: INOUT });
const Hook: React.FC<{ t: number }> = ({ t }) => {
  const bar = k(t, 0.1, 0.4);
  return (
    <>
      <Col top={740} gap={14}>
        <div style={{ position: "relative", height: 300, width: "100%", display: "flex", flexDirection: "column", alignItems: "center", gap: 14 }}>
          <div style={{ position: "absolute", top: 0, display: "flex", flexDirection: "column", alignItems: "center", gap: 14 }}>
            <Ln t={t} a={v(0.02)} b={v(1.38)} size={120}>Quer concluir</Ln>
            <Tag t={t} a={v(0.68)} b={v(1.38)} size={128}>Seus estudos</Tag>
          </div>
          <div style={{ position: "absolute", top: 0, display: "flex", flexDirection: "column", alignItems: "center", gap: 14 }}>
            <Ln t={t} a={v(1.5)} size={120}>E transformar</Ln>
            <Tag t={t} a={v(2.2)} size={128}>O seu futuro?</Tag>
          </div>
        </div>
      </Col>
      <div style={{ position: "absolute", left: 240, top: 1200, width: 600 * bar, height: 16, borderRadius: 8, background: EDGE }} />
      <div style={{ position: "absolute", left: 240, top: 1200, width: CAPX(t) - 240, height: 16, borderRadius: 8, background: BLUE, boxShadow: "0 0 24px rgba(47,123,255,0.6)" }} />
      <div style={{ position: "absolute", left: CAPX(t) - 60, top: 1200 - 104, transform: `scale(${k(t, 0.2, 0.45, BACK).toFixed(3)}) rotate(${(-8 + 8 * k(t, v(3.0), 0.3)).toFixed(1)}deg)` }}><Cap e={1} size={120} /></div>
    </>
  );
};
const Flood: React.FC<{ t: number }> = ({ t }) => {
  if (t < v(3.05) || t > C1 + 0.1) return null;
  const g = interpolate(t, [v(3.05), C1], [0, 1], { ...cl, easing: INOUT });
  const R = 2300;
  return (
    <AbsoluteFill style={{ background: BLUE, clipPath: `circle(${(g * R).toFixed(0)}px at ${CAPX(t).toFixed(0)}px 1200px)`, zIndex: 20 }}>
    </AbsoluteFill>
  );
};
// ───────── 2 · supletivo EAD + logo ─────────
const Supletivo: React.FC<{ t: number }> = ({ t }) => (
  <Col top={540} gap={18}>
    <div style={{ transform: `scale(${k(t, C1 + 0.05, 0.5, BACK).toFixed(3)})` }}><Cap e={1} size={150} color={WHITE} /></div>
    <Ln t={t} a={v(3.6)} size={182}>Supletivo</Ln>
    <Tag t={t} a={v(4.45)} size={200}>EAD</Tag>
    <div style={{ height: 40 }} />
    <div style={{ overflow: "hidden" }}>
      <Img src={staticFile("helio/logo.png")} style={{ width: 460, display: "block", transform: `translateY(${((1 - k(t, v(4.95), 0.55)) * 100).toFixed(1)}%)` }} />
    </div>
  </Col>
);

// ───────── 3 · ensino médio ─────────
const Ensino: React.FC<{ t: number }> = ({ t }) => (
  <Col top={600} gap={26}>
    <Label t={t} a={v(6.6)}>VOCÊ CONCLUI O</Label>
    <div style={{ height: 10 }} />
    <Ln t={t} a={v(7.58)} size={200}>Ensino</Ln>
    <Tag t={t} a={v(8.55)} size={240}>Médio</Tag>
  </Col>
);

// ───────── 4 · em até 2 meses ─────────
const Meses: React.FC<{ t: number }> = ({ t }) => (
  <Col top={560} gap={26}>
    <div style={{ marginBottom: 20 }}><Clock t={t} a={C3 - 0.05} size={330} /></div>
    <Ln t={t} a={C3 + 0.02} size={130}>Em até</Ln>
    <Tag t={t} a={v(9.75)} size={190}>2 meses!</Tag>
  </Col>
);

// ───────── 5 · 100% online, no seu tempo ─────────
const Online: React.FC<{ t: number }> = ({ t }) => {
  const n = Math.round(100 * interpolate(t, [v(11.3), v(11.95)], [0, 1], { ...cl, easing: INOUT }));
  return (
    <Col top={520} gap={18}>
      <Laptop e={k(t, C4 - 0.05, 0.7)} glow={k(t, v(11.8), 0.5)} size={400} fg={WHITE} ac={BG} />
      <div style={{ height: 10 }} />
      <div style={{ fontFamily: BC, fontStyle: "italic", fontWeight: 900, fontSize: 230, lineHeight: 1, color: WHITE, fontVariantNumeric: "tabular-nums", opacity: k(t, v(11.3), 0.2), transform: `scale(${(0.8 + 0.2 * k(t, v(11.3), 0.5, BACK)).toFixed(3)})` }}>{n}%</div>
      <Tag t={t} a={v(11.78)} size={150}>Online</Tag>
      <div style={{ height: 10 }} />
      <Ln t={t} a={v(12.33)} size={96} color={AZUL.sub} w={700}>No seu tempo</Ln>
    </Col>
  );
};

// ───────── 6 · formação acelerada: três cursos, um por batida ─────────
const CURSOS = [
  { a: v(15.25), top: "Segurança", big: "Pública", c: GOLD, kind: "star" as const },
  { a: v(16.47), top: "Segurança do", big: "Trabalho", c: GREEN, kind: "cross" as const },
  { a: v(17.88), top: "Segurança", big: "Privada", c: BLUE, kind: "lock" as const },
];
const Curso: React.FC<{ t: number; i: number }> = ({ t, i }) => {
  const c = CURSOS[i];
  const e = k(t, c.a - 0.08, 0.5);
  return (
    <div style={{ width: 840, height: 200, borderRadius: 28, background: CARD, border: `3px solid ${c.c}`, display: "flex", alignItems: "center", gap: 36, padding: "0 44px", boxSizing: "border-box", opacity: t < c.a - 0.08 ? 0 : 1, transform: `translateX(${((1 - e) * 260).toFixed(1)}px) scale(${(0.92 + 0.08 * k(t, c.a - 0.08, 0.45, BACK)).toFixed(3)})` }}>
      <Shield e={k(t, c.a, 0.6)} color={c.c} size={118} kind={c.kind} />
      <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start" }}>
        <div style={{ fontFamily: BCN, fontWeight: 700, fontSize: 46, letterSpacing: "0.06em", color: SUB, textTransform: "uppercase", lineHeight: 1.05 }}>{c.top}</div>
        <div style={{ fontFamily: BC, fontStyle: "italic", fontWeight: 900, fontSize: 96, color: c.c === BLUE ? WHITE : c.c, textTransform: "uppercase", lineHeight: 1 }}>{c.big}</div>
      </div>
    </div>
  );
};
const Formacao: React.FC<{ t: number }> = ({ t }) => (
  <Col top={360} gap={30}>
    <Ln t={t} a={v(13.92)} size={140}>Formação</Ln>
    <Tag t={t} a={v(14.45)} size={140}>Acelerada</Tag>
    <div style={{ height: 24 }} />
    <Curso t={t} i={0} />
    <Curso t={t} i={1} />
    <Curso t={t} i={2} />
  </Col>
);
// ───────── 7 · tecnólogo em gestão de segurança privada, em até 1 ano ─────────
const Tecnologo: React.FC<{ t: number }> = ({ t }) => {
  const fill = interpolate(t, [v(22.3), v(23.4)], [0, 12], { ...cl, easing: INOUT });
  return (
    <Col top={370} gap={20}>
      <Shield e={k(t, C6 - 0.1, 0.7)} color={BLUE} size={170} kind="lock" ink={BLUE} />
      <div style={{ height: 6 }} />
      <Label t={t} a={v(19.85)}>TECNÓLOGO EM</Label>
      <Ln t={t} a={v(20.15)} size={130}>Gestão de</Ln>
      <Ln t={t} a={v(20.78)} size={130}>Segurança</Ln>
      <Tag t={t} a={v(21.45)} size={130}>Privada</Tag>
      <div style={{ height: 40 }} />
      <div style={{ display: "flex", gap: 10, opacity: k(t, v(22.0), 0.3) }}>
        {Array.from({ length: 12 }, (_, i) => {
          const on = Math.max(0, Math.min(1, fill - i));
          return <div key={i} style={{ width: 52, height: 30, borderRadius: 8, background: on > 0.5 ? BLUE : "#D3DCEE", transform: `scaleY(${(1 + 0.35 * on * (1 - Math.max(0, Math.min(1, fill - i - 1)))).toFixed(3)})` }} />;
        })}
      </div>
      <div style={{ height: 10 }} />
      <div style={{ display: "flex", alignItems: "baseline", gap: 24 }}>
        <Ln t={t} a={v(22.9)} size={92} color={CLARO.sub} w={800}>Em até</Ln>
        <Ln t={t} a={v(23.2)} size={120} w={900}>1 ano</Ln>
      </div>
    </Col>
  );
};

// ───────── 8 · reconhecido pelo MEC → diploma válido em todo o Brasil (mesmo lugar) ─────────
const Mec: React.FC<{ t: number }> = ({ t }) => (
  <>
    <Col top={300}>
      <Seal e={k(t, C7 - 0.05, 0.7, BACK)} check={k(t, v(25.6), 0.4)} size={360} spin={Math.max(0, t - C7) * 6} />
    </Col>
    <Col top={720} gap={16}>
      <div style={{ position: "relative", width: "100%", height: 300, display: "flex", justifyContent: "center" }}>
        <div style={{ position: "absolute", top: 0, display: "flex", flexDirection: "column", alignItems: "center", gap: 16 }}>
          <Ln t={t} a={v(24.75)} b={v(25.98)} size={140}>Reconhecido</Ln>
          <Tag t={t} a={v(25.3)} b={v(25.98)} size={140} bg={GOLD} color={BG}>Pelo MEC</Tag>
        </div>
        <div style={{ position: "absolute", top: 0, display: "flex", flexDirection: "column", alignItems: "center", gap: 16 }}>
          <Ln t={t} a={v(26.1)} size={118}>Diploma válido</Ln>
          <Tag t={t} a={v(27.2)} size={96}>Em todo o Brasil</Tag>
        </div>
      </div>
      <div style={{ opacity: k(t, v(26.1), 0.3), marginTop: 30 }}><Diploma e={k(t, v(26.1), 0.8)} size={170} /></div>
    </Col>
  </>
);

// ───────── 9 · garanta já sua vaga ─────────
const Contato: React.FC<{ t: number; p: number; size?: number }> = ({ p, size = 76 }) => (
  <div style={{ display: "flex", alignItems: "center", gap: size * 0.29, padding: `${size * 0.29}px ${size * 0.58}px ${size * 0.29}px ${size * 0.4}px`, borderRadius: 999, background: BG, border: `3px solid ${GREEN}`, opacity: Math.min(1, p * 2), transform: `scale(${(0.7 + 0.3 * p).toFixed(3)})` }}>
    <Whats size={size * 1.03} />
    <div style={{ fontFamily: BC, fontStyle: "italic", fontWeight: 800, fontSize: size, color: WHITE, whiteSpace: "nowrap", fontVariantNumeric: "tabular-nums" }}>(00) 00000-0000</div>
  </div>
);
const Cta: React.FC<{ t: number }> = ({ t }) => (
  <Col top={640} gap={22}>
    <Ln t={t} a={v(29.58)} size={170}>Garanta já</Ln>
    <Tag t={t} a={v(30.1)} size={170} bg={GOLD} color={BG}>Sua vaga!</Tag>
    <div style={{ height: 50 }} />
    <Contato t={t} p={k(t, v(31.3), 0.5, BACK)} />
  </Col>
);

// ───────── 10 · cartão final: o slogan em destaque ─────────
const Final: React.FC<{ t: number }> = ({ t }) => (
  <>
    <Col top={380} gap={24}>
      {/* logo sem a linha do slogan (o slogan vem grande logo abaixo); recorte em 82% da altura */}
      <div style={{ overflow: "hidden", height: 238 }}>
        <Img src={staticFile("helio/logo.png")} style={{ width: 560, display: "block", transform: `translateY(${((1 - k(t, C9 + 0.05, 0.6)) * 100).toFixed(1)}%)` }} />
      </div>
      <div style={{ height: 50 }} />
      <Ln t={t} a={FIN.arq - 0.05} size={136}>Arquitetando</Ln>
      <Tag t={t} a={FIN.seu - 0.05} size={156}>Seu futuro</Tag>
    </Col>
    {/* contato em duas linhas e mais alto: fora da faixa de baixo e da coluna de botões do Instagram */}
    <Col top={1140} gap={12}>
      <Contato t={t} p={1} size={58} />
      <div style={{ fontFamily: BCN, fontWeight: 700, fontSize: 38, color: WHITE, whiteSpace: "nowrap", opacity: k(t, C9 + 0.3, 0.4) }}>@suamarca</div>
      <div style={{ display: "flex", alignItems: "center", gap: 12, fontFamily: BCN, fontWeight: 600, fontSize: 38, color: SUB, whiteSpace: "nowrap", opacity: k(t, C9 + 0.3, 0.4) }}>
        <Pin size={26} />
        <span>Shop Master do Cabula · Salvador-BA</span>
      </div>
    </Col>
  </>
);

export const FormacaoTutores: React.FC<{ som?: boolean }> = ({ som = true }) => {
  const t = useCurrentFrame() / FO_FPS;
  return (
    <AbsoluteFill style={{ background: BG, overflow: "hidden" }}>
      <Scene t={t} a={-1} b={C1 + 0.3} inn="none" out="none" tema={ESCURO} dir={1} hits={[v(0.68), v(2.2)]}><Hook t={t} /></Scene>
      <Flood t={t} />
      <Scene t={t} a={C1} b={C2} inn="none" out="left" tema={AZUL} dir={-1} hits={[v(4.45), v(4.95)]}><Supletivo t={t} /></Scene>
      <Scene t={t} a={C2} b={C3} inn="left" out="up" tema={CLARO} dir={1} hits={[v(7.58), v(8.55)]}><Ensino t={t} /></Scene>
      <Scene t={t} a={C3} b={C4} inn="up" out="zoom" tema={ESCURO} dir={-1} hits={[v(9.75)]}><Meses t={t} /></Scene>
      <Scene t={t} a={C4} b={C5} inn="zoom" out="right" tema={AZUL} dir={1} hits={[v(11.78), v(12.33)]} iris={[540, 760]}><Online t={t} /></Scene>
      <Scene t={t} a={C5} b={C6 + 0.4} inn="right" out="none" tema={ESCURO} dir={-1} hits={[v(14.45), v(15.25), v(16.47), v(17.88)]}><Formacao t={t} /></Scene>
      <Scene t={t} a={C6} b={C7} inn="none" out="down" tema={CLARO} dir={1} hits={[v(21.45), v(23.2)]} iris={[225, 1415]}><Tecnologo t={t} /></Scene>
      <Scene t={t} a={C7} b={C8} inn="down" out="left" tema={ESCURO} dir={-1} hits={[v(25.3), v(25.6), v(27.2)]}><Mec t={t} /></Scene>
      <Scene t={t} a={C8} b={C9} inn="left" out="up" tema={AZUL} dir={1} hits={[v(30.1), v(31.3)]}><Cta t={t} /></Scene>
      <Scene t={t} a={C9} b={FO_DUR + 1} inn="up" out="none" tema={ESCURO} dir={-1} hits={[FIN.seu - 0.05, FIN.futuro]}><Final t={t} /></Scene>
      {som ? <Audio src={staticFile("helio/formacao-mix-v3.wav")} /> : null}
    </AbsoluteFill>
  );
};

import { loadFont } from "@remotion/google-fonts/BarlowCondensed";
import React from "react";
import { Easing, interpolate } from "remotion";

// Peças do motion "Formação acelerada" (Tutores.ed, cliente hélio silva). Identidade das artes de divulgação:
// azul-marinho quase preto, azul elétrico, branco, letra condensada em itálico bem pesada, etiqueta azul inclinada
// atrás da palavra-chave; dourado e verde só nos cursos de segurança, como nas artes.

const { fontFamily: BC } = loadFont("italic", { weights: ["700", "800", "900"], subsets: ["latin", "latin-ext"] });
const { fontFamily: BCN } = loadFont("normal", { weights: ["600", "700"], subsets: ["latin", "latin-ext"] });
export { BC, BCN };

export const BG = "#060B1A";
export const CARD = "#0C1631";
export const EDGE = "#1E3266";
export const BLUE = "#2F7BFF";
export const WHITE = "#F4F7FF";
export const SUB = "#A3B3D3";
export const GOLD = "#F2B632";
export const GREEN = "#3DBA5A";

export const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const OUT = Easing.bezier(0.16, 1, 0.3, 1);
export const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
export const BACK = Easing.out(Easing.back(1.3));
export const k = (t: number, a: number, d = 0.45, e = OUT) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: e });
export const kin = (t: number, a: number, d = 0.3) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: Easing.in(Easing.cubic) });

// fundo de cada cena (inversão: marinho, azul e claro se alternam); texto, etiqueta e ícones seguem o tema
export type Tema = { bg: string; fg: string; tag: string; tagFg: string; ac: string; sub: string };
export const ESCURO: Tema = { bg: BG, fg: WHITE, tag: BLUE, tagFg: WHITE, ac: BLUE, sub: SUB };
export const AZUL: Tema = { bg: BLUE, fg: WHITE, tag: BG, tagFg: WHITE, ac: WHITE, sub: "#D9E6FF" };
export const CLARO: Tema = { bg: WHITE, fg: BG, tag: BLUE, tagFg: WHITE, ac: BLUE, sub: "#4A5B80" };
export const Th = React.createContext<Tema>(ESCURO);

// ───────── texto: sobe da linha por máscara, fica parado, desce pela máscara na saída ─────────
export const Ln: React.FC<{ t: number; a: number; b?: number; size: number; color?: string; w?: number; it?: boolean; ls?: string; children: React.ReactNode }> = ({ t, a, b = 999, size, color, w = 800, it = true, ls = "0", children }) => {
  const th = React.useContext(Th);
  const e = k(t, a, 0.42);
  const pop = k(t, a, 0.5, BACK);
  const o = kin(t, b, 0.26);
  return (
    <div style={{ overflow: "hidden", padding: `0 ${size * 0.12}px ${size * 0.04}px`, margin: `0 ${-size * 0.12}px ${-size * 0.04}px`, visibility: t < a || o >= 1 ? "hidden" : "visible" }}>
      <div style={{ fontFamily: it ? BC : BCN, fontStyle: it ? "italic" : "normal", fontWeight: w, fontSize: size, lineHeight: 1.0, color: color ?? th.fg, letterSpacing: ls, textTransform: "uppercase", whiteSpace: "nowrap", textAlign: "center", transform: `translateY(${((1 - e) * 108 - o * 108).toFixed(2)}%) scale(${(1.15 - 0.15 * pop).toFixed(4)}) rotate(${((1 - e) * -5).toFixed(2)}deg)` }}>{children}</div>
    </div>
  );
};

// etiqueta inclinada (como "EAD" e "SEUS ESTUDOS" nas artes): o bloco corre da esquerda e a palavra sobe dentro dele
export const Tag: React.FC<{ t: number; a: number; b?: number; size: number; bg?: string; color?: string; children: React.ReactNode }> = ({ t, a, b = 999, size, bg, color, children }) => {
  const th = React.useContext(Th);
  bg = bg ?? th.tag;
  color = color ?? th.tagFg;
  const g = k(t, a, 0.38);
  const o = kin(t, b, 0.26);
  return (
    <div style={{ position: "relative", padding: `${size * 0.06}px ${size * 0.26}px ${size * 0.02}px`, visibility: t < a || o >= 1 ? "hidden" : "visible" }}>
      <div style={{ position: "absolute", inset: 0, background: bg, borderRadius: size * 0.08, transform: `skewX(-12deg) scaleX(${(g * (1 - o)).toFixed(4)})`, transformOrigin: o > 0 ? "100% 50%" : "0% 50%" }} />
      <div style={{ position: "relative" }}>
        <Ln t={t} a={a + 0.12} b={b - 0.04} size={size} color={color} w={900}>{children}</Ln>
      </div>
    </div>
  );
};

// rótulo pequeno: traço azul + caixa alta espaçada
export const Label: React.FC<{ t: number; a: number; b?: number; color?: string; children: React.ReactNode }> = ({ t, a, b = 999, color, children }) => {
  const th = React.useContext(Th);
  color = color ?? th.ac;
  const e = k(t, a, 0.4) * (1 - kin(t, b, 0.25));
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 18, opacity: e, fontFamily: BCN, fontWeight: 700, fontSize: 38, letterSpacing: "0.2em", color, whiteSpace: "nowrap" }}>
      <span style={{ width: 54 * e, height: 5, borderRadius: 3, background: color }} />
      {children}
      <span style={{ width: 54 * e, height: 5, borderRadius: 3, background: color }} />
    </div>
  );
};

