// ───────── ícones em traço (desenham-se) ─────────
export const S = (c: string = WHITE, w = 10) => ({ fill: "none", stroke: c, strokeWidth: w, strokeLinecap: "round" as const, strokeLinejoin: "round" as const });
export const draw = (e: number) => ({ pathLength: 1, strokeDasharray: 1, strokeDashoffset: 1 - e });

// relógio com linhas de velocidade; ponteiro gira rápido (o tempo voando)
export const Clock: React.FC<{ t: number; a: number; size?: number; fg?: string; ac?: string }> = ({ t, a, size = 300, fg: WHITE = "#F4F7FF", ac: BLUE = "#2F7BFF" }) => {
  const e = k(t, a, 0.6), sp = k(t, a + 0.15, 0.5);
  const ang = Math.max(0, t - a) * 540;
  return (
    <svg viewBox="0 0 300 300" width={size} height={size} style={{ overflow: "visible" }}>
      {[0, 1, 2].map((i) => <path key={i} d={`M${-40 - i * 30} ${110 + i * 40} H${40 - i * 10}`} {...S(BLUE, 10)} {...draw(sp)} opacity={0.9 - i * 0.2} />)}
      <circle cx={150} cy={150} r={118} {...S(WHITE, 14)} {...draw(e)} />
      <circle cx={150} cy={150} r={96} {...S(BLUE, 6)} {...draw(e)} opacity={0.7} />
      <path d="M150 34 V12 M120 14 H180" {...S(WHITE, 12)} {...draw(e)} />
      <g style={{ transform: `rotate(${ang.toFixed(1)}deg)`, transformOrigin: "150px 150px" }}>
        <path d="M150 150 V80" {...S(WHITE, 12)} {...draw(e)} />
      </g>
      <g style={{ transform: `rotate(${(ang / 12 + 90).toFixed(1)}deg)`, transformOrigin: "150px 150px" }}>
        <path d="M150 150 V104" {...S(BLUE, 12)} {...draw(e)} />
      </g>
      <circle cx={150} cy={150} r={12 * e} fill={WHITE} />
    </svg>
  );
};

