// selo "Reconhecido pelo MEC" (roseta dourada como na arte)
export const Seal: React.FC<{ e: number; check: number; size?: number; spin?: number }> = ({ e, check, size = 380, spin = 0 }) => {
  const teeth = Array.from({ length: 24 }, (_, i) => {
    const a = (i / 24) * Math.PI * 2;
    const r = i % 2 ? 150 : 168;
    return `${(190 + Math.cos(a) * r).toFixed(1)},${(190 + Math.sin(a) * r).toFixed(1)}`;
  }).join(" ");
  return (
    <svg viewBox="0 0 380 380" width={size} height={size} style={{ overflow: "visible" }}>
      <g style={{ transform: `rotate(${spin.toFixed(2)}deg) scale(${e.toFixed(4)})`, transformOrigin: "190px 190px" }}>
        <polygon points={teeth} fill={GOLD} />
      </g>
      <circle cx={190} cy={190} r={128 * e} fill="#0A1124" />
      <circle cx={190} cy={190} r={114} {...S(GOLD, 5)} {...draw(k(e, 0.3, 0.7))} />
      <g opacity={k(e, 0.5, 0.5)}>
        <text x={190} y={142} textAnchor="middle" fontFamily="Barlow Condensed, sans-serif" fontWeight={700} fontSize={19} letterSpacing={2} fill={WHITE}>RECONHECIDO PELO</text>
        <text x={190} y={222} textAnchor="middle" fontFamily="Barlow Condensed, sans-serif" fontStyle="italic" fontWeight={900} fontSize={88} fill={WHITE}>MEC</text>
      </g>
      <path d="M164 248 l18 18 l36 -40" {...S(GOLD, 12)} {...draw(check)} />
    </svg>
  );
};

